// los ojos de Vigi siguen al mouse (o al dedo)
let quieto = null;
function mira(x, y) {
  const el = document.getElementById('vigi'); if (!el) return;
  el.classList.add('sigue'); clearTimeout(quieto); quieto = setTimeout(() => el.classList.remove('sigue'), 4000);
  const svg = el.querySelector('.vg-b svg'); if (!svg) return; const r = svg.getBoundingClientRect(), k = r.width / 120;
  el.querySelectorAll('.vg-pu').forEach(pu => { const cx = r.left + Number(pu.getAttribute('cx')) * k, cy = r.top + Number(pu.getAttribute('cy')) * k;
    const dx = x - cx, dy = y - cy, d = Math.hypot(dx, dy) || 1, m = Math.min(6, d / 25);
    pu.style.transform = 'translate(' + (dx / d * m).toFixed(2) + 'px,' + (dy / d * m).toFixed(2) + 'px)'; });
}
document.addEventListener('mousemove', e => mira(e.clientX, e.clientY), {passive: true});
document.addEventListener('touchmove', e => { const t = e.touches[0]; if (t) mira(t.clientX, t.clientY); }, {passive: true});
